// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Json = any;
const V: Json = JSON.parse(readFileSync(new URL("../../server-rs/crates/rh-proto/vectors/rust.json", import.meta.url), "utf8"));
const h = (s: string) => fromHex(s);

function frameFromJson(j: Json): Frame {
  const rec = (r: Json) => ({ seq: r.seq, epoch: r.epoch, nonce: h(r.nonce), ct: h(r.ct) });
  switch (j.type) {
    case "open":
      return { type: "open", ch: j.ch, peer: j.peer };
    case "data":
      return { type: "data", ch: j.ch, payload: h(j.payload) };
    case "close":
      return { type: "close", ch: j.ch, code: j.code, reason: j.reason };
    case "credit":
      return { type: "credit", ch: j.ch, bytes: j.bytes };
    case "ping":
    case "pong":
      return { type: j.type, nonce: j.nonce };
    case "append":
      return { type: "append", ch: j.ch, stream: h(j.stream), expectSeq: j.expectSeq, records: j.records.map(rec) };
    case "ack":
    case "conflict":
      return { type: j.type, ch: j.ch, stream: h(j.stream), head: j.head };
    case "sub":
      return { type: "sub", ch: j.ch, stream: h(j.stream), fromSeq: j.fromSeq };
    case "recs":
      return { type: "recs", ch: j.ch, stream: h(j.stream), records: j.records.map(rec) };
    case "gone":
      return { type: "gone", ch: j.ch, stream: h(j.stream), firstSeq: j.firstSeq };
    case "checkpoint":
      return { type: "checkpoint", ch: j.ch, stream: h(j.stream), uptoSeq: j.uptoSeq, manifest: h(j.manifest) };
    case "ephemeral":
      return { type: "ephemeral", ch: j.ch, stream: h(j.stream), payload: h(j.payload) };
    case "chain":
      return { type: "chain", ch: j.ch, entries: j.entries.map(h) };
    case "head":
      return { type: "head", ch: j.ch, head: h(j.head) };
    case "page":
      return { type: "page", ch: j.ch, stream: h(j.stream), hash: h(j.hash), data: h(j.data) };
    case "attest":
      return { type: "attest", ch: j.ch, attestation: h(j.attestation) };
    case "pushSend":
      return { type: "pushSend", ch: j.ch, subscription: j.subscription, ttl: j.ttl, payload: h(j.payload) };
    case "unknown":
      return { type: "unknown", ty: j.ty, ch: j.ch, payload: h(j.payload) };
  }
  throw new Error(`unknown frame ${j.type}`);
}

function muxFromJson(j: Json): MuxFrame {
  switch (j.type) {
    case "open":
      return { type: "open", sid: j.sid, class: j.class, window: j.window, meta: h(j.meta) };
    case "data":
      return { type: "data", sid: j.sid, data: h(j.data) };
    case "credit":
      return { type: "credit", sid: j.sid, delta: j.delta };
    case "close":
      return { type: "close", sid: j.sid, code: j.code };
    default:
      return { type: j.type, nonce: j.nonce };
  }
}

test("every hub frame kind encodes to Rust's bytes and decodes back", () => {
  assert.ok(V.frames.length >= 17);
  for (const { frame, hex: bytes } of V.frames) {
    const built = frameFromJson(frame);
    assert.equal(hex(encodeFrame(built)), bytes, frame.type);
    assert.deepEqual(decodeFrame(h(bytes)), built, frame.type);
  }
});

test("mux frames match, and the scheduler drains in Rust's order", () => {
  for (const { frame, hex: bytes } of V.mux.frames) {
    assert.equal(hex(encodeMuxFrame(muxFromJson(frame))), bytes);
    assert.deepEqual(decodeMuxFrame(h(bytes)), muxFromJson(frame));
  }
  // The same operations as `rh_proto::mux::scheduling_scenario`.
  const mux = new Mux("initiator");
  const enc = new TextEncoder();
  const blob = mux.open("blob", enc.encode("file"));
  const rpc = mux.open("rpc", enc.encode("GET /api/sessions"));
  const term = mux.open("term", enc.encode("t-1"));
  const feed = mux.open("mux", enc.encode("/api/events?v=2"));
  mux.send(blob, new Uint8Array(BLOB_CHUNK + 10).fill(0xbb));
  mux.send(rpc, enc.encode("request body"));
  mux.send(feed, enc.encode("sub"));
  mux.send(term, enc.encode("ls\r"));
  mux.close(rpc, 0);
  mux.ping(7);
  const out: string[] = [];
  for (let f = mux.poll(); f; f = mux.poll()) out.push(hex(encodeMuxFrame(f)));
  assert.deepEqual(out, V.mux.scenario.frames);
});

test("the WebCrypto Noise IK writes and reads exactly what snow does, through rekeys", async () => {
  const n = V.noise;
  const binding = n.binding;
  assert.equal(hex(prologue(binding)), n.prologue);
  const device = await keyPairFromSecret(h(n.initiator.static));
  const agent = await keyPairFromSecret(h(n.responder.static));
  assert.equal(hex(device.publicKey), n.initiator.staticPublic);
  assert.equal(hex(agent.publicKey), n.responder.staticPublic);

  const initiator = await Initiator.create(device, agent.publicKey, binding, await keyPairFromSecret(h(n.initiator.ephemeral)));
  const m1 = await initiator.writeHello(n.hello.timestampMs, h(n.hello.payload));
  assert.equal(hex(m1), n.hello.message, "first message");

  const responder = await Responder.create(agent, binding, await keyPairFromSecret(h(n.responder.ephemeral)));
  const hello = await responder.readHello(h(n.hello.message));
  assert.equal(hex(hello.initiatorStatic), n.initiator.staticPublic);
  assert.equal(hello.timestampMs, n.hello.timestampMs);
  assert.equal(hex(hello.payload), n.hello.payload);
  const reply = await responder.writeReply(h(n.reply.payload), n.policy, n.hello.timestampMs);
  assert.equal(hex(reply.message), n.reply.message, "reply");

  const { transport: it, payload } = await initiator.readReply(h(n.reply.message), n.policy, n.hello.timestampMs);
  assert.equal(hex(payload), n.reply.payload);
  // The payloads are the handshake module's: a chain view each way, no request.
  const helloBody = decodeHelloBody(hello.payload);
  assert.equal(helloBody.chainSeq, n.helloBody.chainSeq);
  assert.equal(hex(helloBody.chainHead), n.helloBody.chainHead);
  assert.deepEqual(helloBody.entries.map((e) => hex(encodeEntry(e))), n.helloBody.entries);
  assert.equal(hex(helloBody.client), n.helloBody.client);
  assert.equal(hex(encodeHelloBody(helloBody)), n.hello.payload);
  const replyBody = decodeReplyBody(payload);
  assert.deepEqual(
    { ...replyBody, chainHead: hex(replyBody.chainHead), server: hex(replyBody.server) },
    { status: "accepted", chainSeq: n.replyBody.chainSeq, chainHead: n.replyBody.chainHead, needFrom: 0, server: n.replyBody.server, entries: [] },
  );
  assert.equal(hex(it.handshakeHash), n.handshakeHash);
  assert.equal(hex(reply.transport.handshakeHash), n.handshakeHash);
  const rt = reply.transport;
  for (const msg of n.transport) {
    const [tx, rx] = msg.from === "initiator" ? [it, rt] : [rt, it];
    const sealed = await tx.seal(msg.nowMs, h(msg.data));
    assert.equal(hex(sealed), msg.message, `${msg.from} @${msg.nowMs}`);
    assert.equal(hex(await rx.open(h(msg.message))), msg.data);
  }
});

const hist = () => ChainClock.history();
const entriesOf = (list: string[]) => list.map((e) => decodeEntry(h(e)));

test("a Rust-signed device chain verifies, and re-signing it in WebCrypto gives the same bytes", async () => {
  const c = V.chain;
  const entries = entriesOf(c.entries);
  entries.forEach((e, i) => assert.equal(hex(encodeEntry(e)), c.entries[i]));
  const state = await ChainState.verify(entries, h(c.accountFingerprint), hist());
  assert.equal(state.seq, c.state.seq);
  assert.equal(hex(state.head), c.state.head);
  for (let i = 0; i < entries.length; i++) assert.equal(hex(await entryHash(entries[i]!)), c.hashes[i]);
  for (const d of c.state.devices) assert.equal(state.deviceRecord(d.id)?.status.type, d.status, d.id);
  for (const m of c.state.machines) assert.equal(!!state.machine(m.id), m.active, m.id);
  state.authorizeDevice("dev-0", h(c.devices[0].dhKey));
  assert.throws(() => state.authorizeDevice("dev-1", h(c.devices[1].dhKey)), ChainError);
  assert.equal(hex(state.fullDeviceKey("dev-0")), c.devices[0].dhKey);
  assert.throws(() => state.fullDeviceKey("dev-2"), ChainError, "a limited device does not deliver keys");

  // Ed25519 is deterministic: the same drafts signed in WebCrypto are the same entries.
  const keyFor = async (e: ReturnType<typeof decodeEntry>) =>
    e.draft.signer.type === "device" ? importEd25519Private(h(c.devices[Number(e.draft.signer.id.slice(4))].signSeed)) : importEd25519Private(h(c.accountKeySeed));
  for (const e of entries) {
    const resigned = await signDraft(e.draft, await keyFor(e));
    assert.equal(hex(encodeEntry(resigned)), hex(encodeEntry(e)));
  }
  assert.equal(hex(await publicFromSecret("Ed25519", h(c.accountKeySeed))), c.accountKey);
  assert.equal(hex(await fingerprint(h(c.accountKey))), c.accountFingerprint);
  await assert.rejects(ChainState.verify(entries, new Uint8Array(16), hist()), (e: ChainError) => e.kind === "pinMismatch");
});

test("recovery: RSK derives from RK as in Rust; a join stays pending until approved or the delay passes", async () => {
  const c = V.chain;
  const rk = await recoveryKeys(h(c.recoverySecret));
  assert.equal(hex(rk.signingPublic), c.recoveryKey);
  const joined = await ChainState.verify(entriesOf(c.recovery.joined), undefined, hist());
  assert.deepEqual(joined.pendingRecoveries(), [{ id: c.recovery.deviceId, joinSeq: 5 }]);
  assert.throws(() => joined.authorizeDevice(c.recovery.deviceId, h(c.devices[3].dhKey)), ChainError, "pending: no handshakes");
  const approved = await ChainState.verify(entriesOf(c.recovery.approved), undefined, hist());
  assert.equal(approved.device(c.recovery.deviceId)?.viaRecovery, true);
  // Self-activation, verified live: too early, then fine.
  const live = c.recovery.live;
  const clock = ChainClock.live(live.firstSeenMs, live.liveFromSeq);
  clock.observe(5);
  clock.nowMs = live.earlyMs;
  await assert.rejects(ChainState.verify(entriesOf(c.recovery.activated), undefined, clock), (e: ChainError) => e.kind === "tooEarly" && e.detail.readyMs === live.readyMs);
  clock.nowMs = live.readyMs;
  assert.ok((await ChainState.verify(entriesOf(c.recovery.activated), undefined, clock)).device(c.recovery.deviceId));
  // A verifier that starts after the join (an agent enrolled then, a browser
  // opened then): the pending join is history, but its delay runs from then.
  const lv = c.recovery.lateVerifier;
  const late = ChainClock.live(lv.startMs, lv.liveFromSeq);
  const view = await ChainState.verify(entriesOf(c.recovery.joined), undefined, late);
  assert.equal(late.firstSeen.get(5), lv.startMs, "the inherited join is observed when this verifier started");
  const activation = entriesOf(c.recovery.activated).at(-1)!;
  late.nowMs = lv.earlyMs;
  await assert.rejects(view.apply(activation, late), (e: ChainError) => e.kind === "tooEarly" && e.detail.readyMs === lv.readyMs);
  late.nowMs = lv.readyMs;
  await view.apply(activation, late);
  assert.equal(view.device(c.recovery.deviceId)?.status.type, "active");
  // ...and the same verifier coming back after a reload, from what it saved.
  const resumed = ChainClock.resume(lv.earlyMs, 5, [...late.firstSeen].filter(([seq]) => seq <= 5));
  const reloaded = await ChainState.verify(entriesOf(c.recovery.joined), undefined, resumed);
  await assert.rejects(reloaded.apply(activation, resumed), (e: ChainError) => e.kind === "tooEarly" && e.detail.readyMs === lv.readyMs);
  // A device re-signs the recovery join with RSK: the same bytes.
  const join = entriesOf(c.recovery.joined).at(-1)!;
  assert.equal(hex(encodeEntry(await signDraft(join.draft, rk.signing))), hex(encodeEntry(join)));
});

test("a recovery key carries RSK's proof over the account and its root, the same bytes as Rust's", async () => {
  const c = V.chain;
  const rk = await recoveryKeys(h(c.recoverySecret));
  const genesis = entriesOf(c.entries)[0]!;
  assert.equal(genesis.draft.action.type, "genesis");
  const inChain = genesis.draft.action.type === "genesis" ? genesis.draft.action.recoveryKey! : null;
  assert.equal(hex(inChain!.key), c.recoveryKey);
  assert.equal(hex(inChain!.proof), c.recovery.proof);
  // Ed25519 is deterministic: WebCrypto signs the same proof.
  const mine = await recoveryKeyFor(rk, c.account, h(c.accountKey));
  assert.equal(hex(mine.key), c.recoveryKey);
  assert.equal(hex(mine.proof), c.recovery.proof);
  assert.ok(await verifyRecoveryKey(mine, c.account, h(c.accountKey)));
  assert.equal(await verifyRecoveryKey(mine, "acct-2", h(c.accountKey)), false, "another account");
  assert.equal(await verifyRecoveryKey(mine, c.account, h(c.devices[0].signKey)), false, "another root");
});

test("committed key epochs: the same commitments, and only the committed keys pass", async () => {
  const c = V.chain;
  const k = c.keyEpochs;
  const entries = entriesOf(k.entries);
  entries.forEach((e, i) => assert.equal(hex(encodeEntry(e)), k.entries[i]));
  const state = await ChainState.verify(entries, h(c.accountFingerprint), hist());
  const keyed = entries.slice(-2);
  assert.deepEqual(keyed.map((e) => e.draft.action.type), ["keyEpochs", "keyEpochs"]);
  for (const e of keyed) {
    const resigned = await signDraft(e.draft, await importEd25519Private(h(c.devices[0].signSeed)));
    assert.equal(hex(encodeEntry(resigned)), hex(encodeEntry(e)));
  }
  assert.equal(hex(await userKeyCommit(c.account, 0, h(k.userKey))), k.userCommit);
  for (let i = 0; i < k.machineKeys.length; i++) assert.equal(hex(await machineKeyCommit(c.account, "m-1", i, h(k.machineKeys[i]))), k.machineCommits[i]);
  const first = keyed[0]!.draft.action;
  assert.ok(first.type === "keyEpochs" && first.user && hex(first.user.hash) === k.userCommit && hex(first.machines[0]!.hash) === k.machineCommits[0]);
  assert.equal(state.userKeyEpochs(), 1);
  assert.equal(state.latestUserEpoch(), 0);
  assert.equal(state.machineKeyEpochs("m-1"), 2);
  assert.equal(state.latestMachineEpoch("m-1"), 1);
  assert.equal(state.latestMachineEpoch("m-2"), null);
  await state.checkUserKey(0, h(k.userKey));
  await state.checkMachineKey("m-1", 0, h(k.machineKeys[0]));
  await state.checkMachineKey("m-1", 1, h(k.machineKeys[1]));
  const kind = (want: string) => (e: ChainError) => e instanceof ChainError && e.kind === want;
  await assert.rejects(state.checkUserKey(0, h(k.machineKeys[0])), kind("keyMismatch"));
  await assert.rejects(state.checkUserKey(1, h(k.userKey)), kind("uncommittedKey"));
  await assert.rejects(state.checkMachineKey("m-1", 0, h(k.machineKeys[1])), kind("keyMismatch"));
  await assert.rejects(state.checkMachineKey("m-1", 2, h(k.machineKeys[1])), kind("uncommittedKey"));
  await assert.rejects(state.checkMachineKey("m-2", 0, h(k.machineKeys[0])), kind("uncommittedKey"));
  await assert.rejects(state.checkMachineKey("m-1", 4_294_967_295, h(k.machineKeys[0])), kind("uncommittedKey"));
  // The base chain commits nothing.
  const bare = await ChainState.verify(entriesOf(c.entries), undefined, hist());
  assert.equal(bare.latestUserEpoch(), null);
  await assert.rejects(bare.checkUserKey(0, h(k.userKey)), kind("uncommittedKey"));
});

test("attestations verify across languages", async () => {
  const c = V.chain;
  const state = await ChainState.verify(entriesOf(c.entries), undefined, hist());
  const att = decodeAttestation(h(c.attestation.hex));
  assert.equal(hex(encodeAttestation(att)), c.attestation.hex);
  assert.deepEqual(await state.freshness(c.attestation.requester, [att], c.attestation.nowMs, c.attestation.maxAgeMs), { type: c.attestation.freshness });
  const resigned = await createAttestation(state, "dev-0", await importEd25519Private(h(c.devices[0].signSeed)), att.timeMs);
  assert.equal(hex(encodeAttestation(resigned)), c.attestation.hex);
});

test("every chain Rust refuses is refused here, with the same error", async () => {
  for (const bad of V.chain.invalid) {
    await assert.rejects(ChainState.verify(entriesOf(bad.entries), undefined, hist()), (e: ChainError) => {
      assert.equal(e.kind, bad.error, bad.name);
      return true;
    });
  }
});

test("string fields read as Rust reads them: a byte-order mark is kept, invalid and non-canonical UTF-8 refused", () => {
  const prefixed = (raw: Uint8Array) => Uint8Array.from([raw.length >> 8, raw.length & 0xff, ...raw]);
  assert.ok(V.utf8.kept.some((c: Json) => c.hex.startsWith("efbbbf")));
  for (const c of V.utf8.kept) {
    assert.equal(fromUtf8(h(c.hex)), c.text, c.name);
    assert.equal(new Reader(prefixed(h(c.hex))).str16("text", 64), c.text, c.name);
    assert.equal(hex(utf8(c.text)), c.hex, `${c.name}: the bytes round-trip`);
  }
  assert.ok(V.utf8.invalid.length >= 12);
  for (const c of V.utf8.invalid) {
    assert.throws(() => fromUtf8(h(c.hex)), DecodeError, c.name);
    assert.throws(() => new Reader(prefixed(h(c.hex))).str16("text", 64), DecodeError, c.name);
  }
  // A close frame's reason too (its own decoder before).
  const close = encodeFrame({ type: "close", ch: 1, code: 1000, reason: "﻿bye" });
  assert.deepEqual(decodeFrame(close), { type: "close", ch: 1, code: 1000, reason: "﻿bye" });
});

test("rollback, forks and merges", async () => {
  const entries = entriesOf(V.chain.entries);
  const full = await ChainState.verify(entries, undefined, hist());
  const seen = full.checkpoint();
  const older = await ChainState.verify(entries.slice(0, 3), undefined, hist());
  assert.throws(() => older.checkExtends(seen), (e: ChainError) => e.kind === "rollback");
  full.checkExtends(older.checkpoint());
  assert.throws(() => full.checkExtends({ seq: seen.seq, head: new Uint8Array(32) }), (e: ChainError) => e.kind === "fork");
  assert.equal(await older.merge(full.suffix(3), hist()), 2);
  assert.deepEqual(older.checkpoint(), seen);
});

// ---- chain v3 (`docs/local-aggregator.md` §3): Rust's `chainV3` section.

const acceptJson = (a: Accept) => (a.type === "devices" ? { kind: "devices", ids: a.ids } : { kind: a.type });

/** Every signing key the v3 vectors use, by signer: devices by id, the recovery key, passkey slots by slot. */
async function v3Signers(): Promise<(e: Entry) => Promise<CryptoKey>> {
  const c = V.chain;
  const v = V.chainV3;
  const devices = new Map<string, string>([
    ...c.devices.map((d: Json) => [d.id, d.signSeed] as [string, string]),
    [c.machine.id, c.machine.signSeed],
    ...v.extraDevices.map((d: Json) => [d.id, d.signSeed] as [string, string]),
  ]);
  const slots = new Map<string, string>(v.passkeys.map((p: Json) => [p.slot, p.seed]));
  const rk = await recoveryKeys(h(c.recoverySecret));
  return async (e) => {
    const s = e.draft.signer;
    if (s.type === "account") return importEd25519Private(h(c.accountKeySeed));
    if (s.type === "recovery") {
      // Words set after the fixture's sign some joins (write gate: d-s, d-t).
      const seed = v.recoverySigners[String(e.draft.seq)];
      return seed ? importEd25519Private(h(seed)) : rk.signing;
    }
    if (s.type === "passkey") return importEd25519Private(h(slots.get(s.slot)!));
    return importEd25519Private(h(devices.get(s.id)!));
  };
}

test("chain v3: Rust's v3 chain verifies here entry for entry, re-signs to the same bytes, and maps to the same state", async () => {
  const v = V.chainV3;
  const entries = entriesOf(v.entries);
  entries.forEach((e, i) => assert.equal(hex(encodeEntry(e)), v.entries[i], `entry ${i} round-trips`));
  assert.deepEqual(
    entries.map((e) => e.draft.version),
    v.versions,
  );
  for (let i = 0; i < entries.length; i++) assert.equal(hex(await entryHash(entries[i]!)), v.hashes[i]);
  // Ed25519 is deterministic: WebCrypto signs every entry to Rust's bytes.
  const keyFor = await v3Signers();
  for (const e of entries) assert.equal(hex(encodeEntry(await signDraft(e.draft, await keyFor(e)))), hex(encodeEntry(e)), `entry ${e.draft.seq} re-signed`);
  // Every step verifies on its own, and the chain moved to v3 at its first v3 entry.
  for (const step of v.steps) {
    const prefix = await ChainState.verify(entries.slice(0, step.seq + 1), undefined, hist());
    assert.equal(prefix.seq, step.seq, step.label);
  }
  const state = await ChainState.verify(entries, undefined, hist());
  const s = v.state;
  assert.equal(state.seq, s.seq);
  assert.equal(hex(state.head), s.head);
  assert.equal(state.isV3, true);
  assert.equal(state.v3From, s.v3From);
  assert.equal(state.hostKeyDue, null);
  assert.equal(state.currentRecoveryKey, s.recoveryKey, "removing the recovered device cleared RK");
  assert.deepEqual(
    state.allDevices().map((d) => ({
      id: d.info.id,
      host: d.host,
      admin: d.admin,
      status: d.status.type,
      viaRecovery: d.viaRecovery,
      viaPasskey: d.viaPasskey,
      addedSeq: d.addedSeq,
      activatedSeq: d.activatedSeq,
    })),
    s.devices,
  );
  assert.deepEqual(
    state
      .allDevices()
      .filter((d) => state.machine(d.info.id))
      .map((d) => d.info.id),
    s.machines,
  );
  assert.deepEqual(
    state.hosts().filter((d) => d.status.type === "active").map((d) => d.info.id),
    s.machines,
  );
  assert.deepEqual(
    state.admins().map((d) => d.info.id),
    s.admins,
  );
  assert.deepEqual(
    state.allSlots().map((r) => ({ slot: r.slot.slot, setBy: r.setBy, removed: r.removed, addedSeq: r.addedSeq })),
    s.slots,
  );
  assert.equal(state.slot("p-1"), undefined, "removing the admin that registered p-1 voided it");
  // Demoting d-y voided the slot it registered; it stays a device.
  assert.equal(state.slot("p-3"), undefined, "demoting the admin that registered p-3 voided it");
  assert.equal(state.device("d-y")?.admin, false);
  // Write gate: d-s came back with RSK4 and was demoted after RSK5 was set — RSK5 stood, and d-t came back with it;
  // removing d-t, which knew the current words, voided them.
  const stepSeq = (label: string) => v.steps.find((s: Json) => s.label === label).seq;
  const afterDemoteS = await ChainState.verify(entries.slice(0, stepSeq("demoteS") + 1), undefined, hist());
  assert.ok(afterDemoteS.currentRecoveryKey, "words d-s never knew stand");
  const afterRemoveS = await ChainState.verify(entries.slice(0, stepSeq("removeS") + 1), undefined, hist());
  assert.deepEqual(afterRemoveS.currentRecoveryKey, afterDemoteS.currentRecoveryKey, "nor does its (v3) removal void them");
  assert.equal(state.currentRecoveryKey, null);
  // Re-review D1: m-1 stopped and restarted (its policy restarted from admins, then set to h-2 again), and ran AI.
  assert.deepEqual(acceptJson(state.acceptPolicy("m-1")), { kind: "devices", ids: ["h-2"] });
  assert.equal(state.deviceRecord("m-1")?.ranAi, true);
  assert.equal(state.deviceRecord("dev-0")?.ranAi, false);
  await state.checkMachineKey("m-1", 1, h(v.keys.m1b));
  for (const a of s.accept) assert.deepEqual(acceptJson(state.acceptPolicy(a.host)), a.from, a.host);
  assert.equal(state.userKeyEpochs(), s.userKeyEpochs);
  for (const [host, n] of Object.entries(s.machineKeyEpochs)) assert.equal(state.machineKeyEpochs(host), n, host);
  // The committed keys are the vectors' keys.
  await state.checkUserKey(0, h(v.keys.userKey));
  await state.checkMachineKey("m-1", 0, h(v.keys.m1));
  await state.checkMachineKey("h-2", 0, h(v.keys.h2[0]));
  await state.checkMachineKey("h-2", 1, h(v.keys.h2[1]));
  await state.checkMachineKey("h-2", 2, h(v.keys.h2[2]));
  // The passkey slots' proofs are WebCrypto's signatures too.
  for (const p of v.passkeys) {
    const proof = await passkeySlotProof(await importEd25519Private(h(p.seed)), h(p.key), v.account, h(V.chain.accountKey), p.slot, h(p.credHash), h(p.saltNonce));
    assert.equal(hex(proof), p.proof, p.slot);
    assert.equal(hex(await publicFromSecret("Ed25519", h(p.seed))), p.key);
    const slot = { slot: p.slot, key: h(p.key), proof, credHash: h(p.credHash), saltNonce: h(p.saltNonce), grants: p.grants, selfActivate: p.selfActivate };
    assert.ok(await verifyPasskeySlot(slot, v.account, h(V.chain.accountKey)));
    assert.equal(await verifyPasskeySlot({ ...slot, slot: "p-9" }, v.account, h(V.chain.accountKey)), false, "another slot");
  }
  // v2's views of what is left: dev-0 the only admin (full device), m-1 and h-2 hosts, not admins.
  assert.equal(hex(state.fullDeviceKey("dev-0")), V.chain.devices[0].dhKey);
  assert.throws(() => state.fullDeviceKey("h-2"), (e: ChainError) => e.kind === "unknownDevice");
  assert.throws(() => state.fullDeviceKey("d-p"), (e: ChainError) => e.kind === "unknownDevice");
  assert.deepEqual(state.pendingRecoveries(), []);
  assert.deepEqual(state.pendingPasskeyJoins(), []);
});

test("chain v3: who may control whom is Rust's", async () => {
  const v = V.chainV3;
  const state = await ChainState.verify(entriesOf(v.entries), undefined, hist());
  for (const c of v.control) {
    let error: string | null = null;
    try {
      state.mayControl(c.device, c.host);
    } catch (e) {
      assert.ok(e instanceof ChainError);
      error = e.kind;
    }
    assert.deepEqual({ ok: error === null, error }, { ok: c.ok, error: c.error }, `${c.device} → ${c.host}`);
  }
  // authorizeControl: the key, then the policy; never itself.
  const hostKey = (id: string) => h(V.chainV3.extraDevices.find((d: Json) => d.id === id).dhKey);
  state.authorizeControl("h-2", hostKey("h-2"), "m-1");
  assert.throws(() => state.authorizeControl("h-2", hostKey("d-p"), "m-1"), (e: ChainError) => e.kind === "unknownDevice");
  assert.throws(() => state.authorizeControl("m-1", h(V.chain.machine.dhKey), "m-1"), (e: ChainError) => e.kind === "selfControl");
});

test("chain v3: every chain Rust refuses is refused here, with the same error", async () => {
  assert.ok(V.chainV3.invalid.length >= 25);
  let rules = 0;
  for (const bad of V.chainV3.invalid) {
    let kind: string | null = null;
    let reason: string | undefined;
    try {
      await ChainState.verify(entriesOf(bad.entries), undefined, hist());
    } catch (e) {
      assert.ok(e instanceof ChainError, `${bad.name}: ${e}`);
      kind = e.kind;
      reason = e.detail.reason;
    }
    assert.equal(kind, bad.error, bad.name);
    // The rule, not only the kind (review finding 10): the same words as Rust's.
    if (bad.rule) {
      assert.equal(reason, bad.rule, bad.name);
      rules += 1;
    }
  }
  assert.ok(rules >= 15, `${rules} refusals named by their rule`);
});

