test("chain v3: a passkey join activates itself only a day after this verifier first saw it", async () => {
  const p = V.chainV3.passkeyActivation;
  const entries = entriesOf(p.entries);
  const activate = decodeEntry(h(p.activate));
  assert.equal(activate.draft.signer.type, "passkey");
  const clock = ChainClock.live(p.firstSeenMs, p.joinSeq);
  const view = await ChainState.verify(entries.slice(0, p.joinSeq), undefined, hist());
  await view.apply(entries[p.joinSeq]!, clock);
  assert.equal(clock.firstSeen.get(p.joinSeq), p.firstSeenMs);
  assert.deepEqual(view.pendingPasskeyJoins(), [{ id: "d-p", joinSeq: p.joinSeq }]);
  assert.deepEqual(view.pendingRecoveries(), [], "a passkey join is not a recovery");
  assert.throws(() => view.authorizeDevice("d-p", h(V.chainV3.extraDevices.find((d: Json) => d.id === "d-p").dhKey)), ChainError, "pending: no handshakes");
  clock.nowMs = p.earlyMs;
  await assert.rejects(view.apply(activate, clock), (e: ChainError) => e.kind === "tooEarly" && e.detail.readyMs === p.readyMs);
  assert.equal(view.device("d-p"), undefined, "nothing changed");
  clock.nowMs = p.readyMs;
  await view.apply(activate, clock);
  const d = view.device("d-p")!;
  assert.ok(!d.admin && !d.host, "a passkey never brings admin or host");
  assert.equal(d.viaPasskey, "p-1");
  assert.equal(d.activatedSeq, p.joinSeq + 1);
  // A history verifier takes it as it is.
  assert.ok((await ChainState.verify([...entries, activate], undefined, hist())).device("d-p"));
});

test("chain v3: a host key sealed by an admin opens for its device, and only as committed for that host and epoch", async () => {
  const k = V.chainV3.hostKey;
  const ctx: HostKeyContext = { ...k.context };
  assert.equal(hex(encodeHostKeyContext(ctx)), k.contextBytes);
  const mail = decodeHostKeyMail(h(k.mail));
  assert.equal(mail.host, ctx.host);
  assert.equal(hex(mail.sealed), k.sealed);
  assert.equal(hex(encodeHostKeyMail(mail.host, mail.sealed)), k.mail);
  const state = await ChainState.verify(entriesOf(V.chainV3.entries), undefined, hist());
  const dp = V.chainV3.extraDevices.find((d: Json) => d.id === "d-p");
  const me = await keyPairFromSecret(h(dp.dhSecret));
  assert.equal(hex(me.publicKey), dp.dhKey);
  assert.equal(hex(await openHostKey(me, "d-p", state, ctx, mail.sealed)), k.key);
  for (const bad of [{ ...ctx, host: "m-1" }, { ...ctx, epoch: 0 }]) {
    await assert.rejects(openHostKey(me, "d-p", state, bad, mail.sealed), (e: WrapError) => e instanceof WrapError && e.kind === "open");
  }
  await assert.rejects(openHostKey(me, "dev-0", state, ctx, mail.sealed), (e: WrapError) => e.kind === "wrongRecipient");
  await assert.rejects(openHostKey(me, "d-p", state, { ...ctx, sender: "h-2" }, mail.sealed), (e: WrapError) => e.kind === "unknownSender", "a host is no key sender");
  // A host key is neither a user key nor the host's own machine key delivery: another purpose byte.
  await assert.rejects(openFrom(me, h(V.chain.devices[0].dhKey), { purpose: "machineKey", account: ctx.account, sender: ctx.sender, recipient: ctx.recipient, epoch: ctx.epoch }, mail.sealed));
  assert.throws(() => decodeHostKeyMail(h(k.mail).slice(0, 2 + 3 + 59)));
  // The freshness windows: control a week, management twelve hours.
  assert.equal(CONTROL_FRESHNESS_MS, V.chainV3.freshness.controlMs);
  assert.equal(MANAGE_FRESHNESS_MS, V.chainV3.freshness.manageMs);
  assert.equal(FRESHNESS_MAX_AGE_MS, CONTROL_FRESHNESS_MS);
});

test("Rust-sealed records open, are released only under the machine's head, and tampering is caught", async () => {
  const r = V.records;
  const mk = await importMachineKey(h(r.mk));
  const stream = await streamId(mk, r.source, r.id);
  assert.equal(hex(stream), r.streamId);
  const records = r.records.map((x: Json) => decodeSealedRecordBytes(h(x.wire)));
  const head = decodeSignedHead(h(r.head));
  assert.equal(hex(encodeSignedHead(head)), r.head);
  const reader = async () => {
    const lr = LogReader.fromStart(stream, h(r.machineKey));
    await lr.addEpoch(r.epoch, mk);
    return lr;
  };

  const lr = await reader();
  for (let i = 0; i < records.length; i++) {
    await lr.push(records[i]);
    assert.equal(hex(await recordLink(stream, h(r.records[i].prevLink), records[i])), r.records[i].link);
  }
  assert.equal(lr.confirmed, 0, "nothing released before a head");
  const released = await lr.confirm(head);
  assert.deepEqual(released.map((o) => hex(o.body)), r.records.map((x: Json) => x.body));
  assert.equal(released[1]!.fmt, r.records[1].fmt);
  assert.deepEqual(await lr.confirm(decodeSignedHead(h(r.heartbeat))), []);
  assert.equal(lr.freshestMs, decodeSignedHead(h(r.heartbeat)).head.timeMs);

  const kind = (k: RecordError["kind"]) => (e: RecordError) => e.kind === k;
  let x = await reader();
  await x.push(records[0]);
  await assert.rejects(x.push(records[0]), kind("outOfOrder"), "replay");
  await assert.rejects(x.push(records[2]), kind("outOfOrder"), "deletion");
  await x.push(records[1]);
  await assert.rejects(x.confirm(head), kind("incomplete"), "the newest record withheld");
  x = await reader();
  await assert.rejects(x.push({ ...records[1], seq: 0 }), kind("decrypt"));
  const flipped = { ...records[0], ct: Uint8Array.from(records[0].ct, (b: number, i: number) => (i === 3 ? b ^ 1 : b)) };
  await assert.rejects((await reader()).push(flipped), kind("decrypt"));
  const other = LogReader.fromStart(await streamId(mk, r.source, "another"), h(r.machineKey));
  await other.addEpoch(r.epoch, mk);
  await assert.rejects(other.push(records[0]), kind("decrypt"));
  await assert.rejects((await reader()).push({ ...records[0], epoch: r.epoch + 1 }), kind("noKey"));
  // A head under another key, and a reader started from an unsigned head.
  const wrongKey = LogReader.fromStart(stream, h(V.chain.devices[0].signKey));
  await wrongKey.addEpoch(r.epoch, mk);
  for (const rec of records) await wrongKey.push(rec);
  await assert.rejects(wrongKey.confirm(head), kind("badHead"));
  await assert.rejects(LogReader.fromHead(h(V.chain.devices[0].signKey), head), kind("badHead"));
  // Stream names refuse NUL.
  await assert.rejects(streamId(mk, "cla\0ude", "x"), kind("badName"));
});

const ctxOf = (j: Json): SealContext => ({ purpose: j.purpose === 1 ? "userKey" : "machineKey", account: j.account, sender: j.sender, recipient: j.recipient, epoch: j.epoch });

test("Rust's stream names per key epoch: each epoch names the streams anew, and an index entry's se says which", async () => {
  const sn = V.streamNames;
  assert.equal(sn.feature, STREAMS_FEATURE);
  const epochs = new Map<number, Awaited<ReturnType<typeof importMachineKey>>>();
  const ids = new Set<string>();
  for (const e of sn.epochs) {
    const mk = await importMachineKey(h(e.mk));
    epochs.set(e.epoch, mk);
    assert.equal(hex(await indexStream(mk)), e.indexStream);
    assert.equal(hex(await statusStream(mk)), e.statusStream);
    assert.equal(hex(await streamId(mk, sn.source, sn.id)), e.sessionStream);
    for (const id of [e.indexStream, e.statusStream, e.sessionStream]) ids.add(id);
  }
  assert.equal(ids.size, 3 * sn.epochs.length, "no name repeats across epochs");
  for (const { entry, sessionStream } of sn.entries) {
    const mk = sessionNamingKey(epochs, entry.se);
    assert.ok(mk, "a key for the entry's epoch");
    assert.equal(hex(await streamId(mk, entry.source, entry.id)), sessionStream);
  }
});

test("Rust's stream names, pages, manifest and draft: the same names, and they open and verify here", async () => {
  const st = V.streams;
  const mk = await importMachineKey(h(st.mk));
  assert.equal(hex(await indexStream(mk)), st.indexStream);
  assert.equal(hex(await statusStream(mk)), st.statusStream);
  const session = await streamId(mk, st.source, st.id);
  assert.equal(hex(session), st.sessionStream);
  const manifest = decodeManifest(h(st.manifest));
  assert.equal(hex(encodeManifest(manifest)), st.manifest);
  assert.ok(await verifyManifest(manifest, h(st.machineKey)));
  assert.equal(manifestUpto(manifest), st.uptoSeq);
  const reader = await readerFromManifest(h(st.machineKey), manifest);
  await reader.addEpoch(st.epoch, mk);
  assert.equal(reader.confirmed, st.uptoSeq);
  const key = reader.keyFor(st.epoch)!;
  for (let i = 0; i < st.pages.length; i++) {
    const page = st.pages[i];
    assert.equal(hex(await pageHash(h(page.wire))), page.hash);
    const opened = await openManifestPage(key, manifest, i, h(page.wire));
    assert.equal(hex(opened.body), page.body);
    assert.equal(opened.fmt, page.fmt);
  }
  // A page in the wrong slot, or a manifest that is not the machine's, is refused.
  await assert.rejects(openManifestPage(key, manifest, 1, h(st.pages[0].wire)), (e: unknown) => e instanceof RecordError && e.kind === "forged");
  const tampered = { ...manifest, pages: [...manifest.pages].reverse() };
  assert.equal(await verifyManifest(tampered, h(st.machineKey)), false);
  await assert.rejects(readerFromManifest(h(st.machineKey), tampered), (e: unknown) => e instanceof RecordError && e.kind === "badHead");
  for (const p of manifest.pages) assert.equal(p.length, 32);
  // The manifest's bytes past the signed head are the page count, the hashes and the signature: no format.
  assert.equal(h(st.manifest).length, 32 + 8 + 4 + 32 + 8 + 64 + 2 + 32 * st.pages.length + 64);
  const draft = await openEphemeral((e) => (e === st.epoch ? key : undefined), session, h(st.machineKey), st.epoch, h(st.draft.wire));
  assert.equal(draft.epoch, st.epoch);
  assert.equal(hex(draft.body), st.draft.body);
  const refused = (k: RecordError["kind"]) => (e: unknown) => e instanceof RecordError && e.kind === k;
  await assert.rejects(openEphemeral(() => undefined, session, h(st.machineKey), st.epoch, h(st.draft.wire)), refused("noKey"));
  await assert.rejects(openEphemeral(() => key, session, h(st.machineKey), st.epoch + 1, h(st.draft.wire)), refused("malformed"), "a draft under an older epoch than the reader's");
  await assert.rejects(openEphemeral(() => key, session, h(V.chain.devices[0].signKey), st.epoch, h(st.draft.wire)), refused("badHead"), "not the machine's signature");
  const flipped = Uint8Array.from(h(st.draft.wire), (b, i) => (i === 20 ? b ^ 1 : b));
  await assert.rejects(openEphemeral(() => key, session, h(st.machineKey), st.epoch, flipped), refused("badHead"), "the signature covers the ciphertext");
  assert.deepEqual(
    { feed: FMT_FEED_V1, index: FMT_INDEX_V1, status: FMT_STATUS_V1, draft: FMT_DRAFT_V1 },
    st.formats,
  );
});

test("Rust's recovery words, recovery package, CPace run and pairing delivery agree here", async () => {
  const p = V.pairing;
  for (const m of p.mnemonic) {
    assert.equal((await mnemonicFromEntropy(h(m.entropy))).join(" "), m.words);
    assert.equal(hex(await entropyFromMnemonic(m.words.toUpperCase())), m.entropy);
  }
  await assert.rejects(entropyFromMnemonic(p.mnemonic[0].words.split(" ").reverse().join(" ")), (e: unknown) => e instanceof MnemonicError);

  // The recovery package: RSK's X25519 twin, computed from the chain's RSK alone.
  const r = p.recovery;
  assert.equal(hex(edwardsToMontgomery(h(r.rskPublic))), r.sealPublic);
  const keys = await recoveryKeys(h(r.rk));
  assert.equal(hex(keys.seal.publicKey), r.sealPublic);
  const chain = await ChainState.verify(r.chain.map((e: string) => decodeEntry(h(e))), undefined, ChainClock.history());
  assert.equal(chain.latestUserEpoch(), r.epoch, "the package's epoch is committed in the chain");
  const ctx = { purpose: "userKey" as const, account: r.account, sender: r.sender, recipient: RECOVERY_RECIPIENT, epoch: r.epoch };
  assert.equal(hex(await openFromRecovery(keys.seal, chain, ctx, h(r.sealed))), r.uk);
  const other = await recoveryKeys(new Uint8Array(16).fill(9));
  await assert.rejects(openFromRecovery(other.seal, chain, ctx, h(r.sealed)));
  // A chain that does not commit the epoch (the fixture's, before any key epochs) refuses the same package.
  const bare = await ChainState.verify(entriesOf(V.chain.entries), undefined, ChainClock.history());
  await assert.rejects(openFromRecovery(keys.seal, bare, ctx, h(r.sealed)), (e: unknown) => e instanceof WrapError && e.kind === "uncommitted");

  // CPace: the same generator, shares and keys from the same scalars.
  const k = p.pake;
  for (const c of k.elligator) assert.equal(hex(elligator2(h(c.u))), c.x);
  const code = utf8(k.code);
  const ci = channelId(k.account, k.device);
  assert.equal(hex(ci), k.ci);
  assert.equal(hex(await cpaceGenerator(code, ci, h(k.sid))), k.generator);
  const a = await Cpace.start("initiator", code, ci, h(k.sid), h(k.initiatorScalar));
  const b = await Cpace.start("responder", code, ci, h(k.sid), h(k.responderScalar));
  assert.equal(hex(a.share), k.ya);
  assert.equal(hex(b.share), k.yb);
  const ka = await a.finish(b.share);
  const kb = await b.finish(a.share);
  assert.equal(hex(ka.pairSecret), k.pairSecret);
  assert.equal(hex(kb.confirmResponder), k.confirmResponder);
  assert.equal(hex(ka.confirmInitiator), k.confirmInitiator);
  const hello = decodePakeHello(h(p.hello));
  await verifyPakeAnswer(decodePakeAnswer(h(p.answer)), hello, ka);
  const wrong = await (await Cpace.start("initiator", utf8("00000000"), ci, h(k.sid), h(k.initiatorScalar))).finish(b.share);
  await assert.rejects(verifyPakeAnswer(decodePakeAnswer(h(p.answer)), hello, wrong), (e: unknown) => e instanceof PairingError && e.kind === "badAnswer");

  // The QR offer and the delivery it leads to.
  const offer = offerFromText(p.offer.text);
  assert.equal(offerText(offer), p.offer.text);
  assert.equal(hex(offer.secret), p.offer.secret);
  // The same offer behind the newer DRP1- prefix reads the same; RHP1- is still what is written.
  assert.ok(p.offer.textDr.startsWith("DRP1-") && p.offer.textDr.slice(5) === p.offer.text.slice(5));
  assert.deepEqual(offerFromText(p.offer.textDr), offer);
  assert.deepEqual(offerFromText(p.offer.textDr.toLowerCase()), offer);
  assert.equal(offerText(offerFromText(p.offer.textDr)), p.offer.text);
  const d = p.delivery;
  const withN = await ChainState.verify(d.chain.map((e: string) => decodeEntry(h(e))), undefined, ChainClock.history());
  const meDh = await keyPairFromSecret(h(d.recipientDhSecret));
  const meSign = await publicFromSecret("Ed25519", h(d.recipientSignSeed));
  const delivery = decodeDelivery(h(d.hex));
  assert.equal(hex(encodeDelivery(delivery)), d.hex);
  const opened = await openDelivery(delivery, offer.secret, withN, d.recipient, meSign, meDh);
  assert.deepEqual(opened.map((x) => [x.epoch, hex(x.key)]), d.uks);
  for (const [epoch, key] of d.uks) await withN.checkUserKey(epoch, h(key));
  await assert.rejects(openDelivery(delivery, new Uint8Array(32), withN, d.recipient, meSign, meDh), (e: unknown) => e instanceof PairingError && e.kind === "badTag");
  await assert.rejects(openDelivery(delivery, offer.secret, chain, d.recipient, meSign, meDh), (e: unknown) => e instanceof PairingError && e.kind === "notListed");
});

test("a reader refused by a head rolls back like Rust's, and heartbeats are held to the confirmed link", async () => {
  const r = V.records;
  const mk = await importMachineKey(h(r.mk));
  const stream = await streamId(mk, r.source, r.id);
  const records = r.records.map((x: Json) => decodeSealedRecordBytes(h(x.wire)));
  const head = decodeSignedHead(h(r.head));
  const reader = LogReader.fromStart(stream, h(r.machineKey));
  await reader.addEpoch(r.epoch, mk);
  await reader.push(records[0]);
  await assert.rejects(reader.confirm(head), (e: unknown) => e instanceof RecordError && e.kind === "incomplete");
  // Rolled back to 0: the same records can be fed again from the start.
  for (const rec of records) await reader.push(rec);
  assert.equal((await reader.confirm(head)).length, records.length);
  assert.equal(reader.confirmedHead?.head.nextSeq, records.length);
  const heartbeat = decodeSignedHead(h(r.heartbeat));
  assert.deepEqual(await reader.confirm(heartbeat), []);
  assert.equal(reader.freshestMs, heartbeat.head.timeMs);
  // A lying heartbeat (another link at the confirmed seq) does not verify as the machine's.
  const lying = { ...heartbeat, head: { ...heartbeat.head, link: new Uint8Array(32).fill(7) } };
  await assert.rejects(reader.confirm(lying), (e: unknown) => e instanceof RecordError && e.kind === "badHead");
  // A saved reader restarts from its confirmed head and carries on.
  const again = await LogReader.fromHead(h(r.machineKey), reader.confirmedHead!);
  assert.equal(again.confirmed, records.length);
});

test("Rust-sealed keys open only from their sender, straight into non-extractable keys", async () => {
  const w = V.wrap;
  const sender = await keyPairFromSecret(h(w.senderSecret));
  assert.equal(hex(sender.publicKey), V.chain.devices[0].dhKey, "the chain's dev-0");
  const chain = await ChainState.verify(entriesOf(V.chain.entries), undefined, hist());
  const [mkSealed, ukSealed] = w.sealed;
  for (const s of w.sealed) {
    const ctx = ctxOf(s.context);
    assert.equal(hex(encodeSealContext(ctx)), s.context.hex);
    const recipient = await keyPairFromSecret(h(s.recipientSecret));
    assert.equal(hex(await openFrom(recipient, sender.publicKey, ctx, h(s.sealed))), s.secret);
  }
  // The agent's view: accept MK only from a current full device of its chain.
  const agent = await keyPairFromSecret(h(mkSealed.recipientSecret));
  const mk = await unwrapMachineKeyFromChain(agent, "m-1", chain, ctxOf(mkSealed.context), h(mkSealed.sealed));
  assert.equal(mk.hkdf.extractable, false);
  const fromRaw = await importMachineKey(h(mkSealed.secret));
  assert.equal(hex(await streamId(mk, "claude", "x")), hex(await streamId(fromRaw, "claude", "x")));
  await assert.rejects(unwrapMachineKeyFromChain(agent, "m-2", chain, ctxOf(mkSealed.context), h(mkSealed.sealed)), (e: WrapError) => e.kind === "wrongRecipient");
  // What the hub could do before: seal its own MK claiming dev-0. Refused.
  await assert.rejects(unwrapMachineKeyFromChain(agent, "m-1", chain, ctxOf(w.forged.context), h(w.forged.sealed)), (e: WrapError) => e.kind === "open");
  // An agent takes MK only as the chain committed it: this chain commits no key for m-1 at epoch 2.
  await assert.rejects(openMachineKey(agent, "m-1", chain, ctxOf(mkSealed.context), h(mkSealed.sealed)), (e: WrapError) => e.kind === "uncommitted");
  await assert.rejects(openMachineKey(agent, "m-1", chain, ctxOf(ukSealed.context), h(mkSealed.sealed)), (e: WrapError) => e.kind === "wrongPurpose");
  // A UK for dev-3, as an AES-GCM key that cannot be exported.
  const dev3 = await keyPairFromSecret(h(ukSealed.recipientSecret));
  const uk = await unwrapSealed(dev3, sender.publicKey, ctxOf(ukSealed.context), h(ukSealed.sealed), { kind: "aes-gcm", usages: ["encrypt", "decrypt"] });
  assert.equal(uk.extractable, false);
  await assert.rejects(crypto.subtle.exportKey("raw", uk));
  await assert.rejects(openFrom(dev3, sender.publicKey, ctxOf(mkSealed.context), h(ukSealed.sealed)), "the wrong context does not open");
  // As a mailed UK, checked against the chain: it commits no user key epoch.
  await assert.rejects(openUserKey(dev3, "dev-3", chain, ctxOf(ukSealed.context), h(ukSealed.sealed)), (e: WrapError) => e.kind === "uncommitted");
  await assert.rejects(openUserKey(dev3, "dev-3", chain, ctxOf(mkSealed.context), h(ukSealed.sealed)), (e: WrapError) => e.kind === "wrongPurpose");
  for (const s of w.symmetric) assert.equal(hex(await unwrapUnder(h(s.key), h(s.context), h(s.wrapped))), s.secret);
  assert.ok(await verifyPairingTag(h(w.pairing.secret), w.pairing.fields.map(h), h(w.pairing.tag)));
  assert.equal(await verifyPairingTag(h(w.pairing.secret), w.pairing.fields.slice(1).map(h), h(w.pairing.tag)), false);
});

test("key checks agree: weak Ed25519 encodings, low-order X25519 keys, non-canonical signatures", async () => {
  assert.deepEqual([...ed25519WeakEncodings()].sort(), [...V.keys.ed25519Weak].sort());
  for (const k of V.keys.x25519LowOrder) assert.equal(await isLowOrderX25519(h(k)), true, k);
  for (const c of V.keys.x25519Candidates) assert.equal(await isValidX25519(h(c.key)), c.valid, `x25519 ${c.key}`);
  for (const c of V.keys.ed25519Candidates) assert.equal(await isValidEd25519Key(h(c.key)), c.valid, `ed25519 ${c.key}`);
  assert.equal(await isLowOrderX25519(h(V.chain.devices[0].dhKey)), false);
  const s = V.keys.signature;
  assert.equal(await ed25519VerifyStrict(h(s.key), h(s.message), h(s.good)), true);
  assert.equal(await ed25519VerifyStrict(h(s.key), h(s.message), h(s.nonCanonical)), false);
  assert.equal(hex(await fingerprint(h(V.identity.signPublic))), V.identity.fingerprint);
});

test("enrollment codes, tokens and proofs agree with Rust", async () => {
  const { parseEnrollCode, formatEnrollCode, enrollToken, enrollProof, verifyEnrollProof, base32, fromBase32 } = await import("../src/lib/e2e/index.js");
  const e = V.identity.enroll;
  const code = parseEnrollCode(e.code);
  assert.equal(formatEnrollCode(code), e.code);
  assert.equal(hex(code.secret), e.secret);
  // The same code behind the newer DR1- prefix reads the same; RH1- is still what is written.
  assert.ok(e.codeDr.startsWith("DR1-") && e.codeDr.slice(4) === e.code.slice(4));
  assert.deepEqual(parseEnrollCode(e.codeDr), code);
  assert.deepEqual(parseEnrollCode(e.codeDr.toLowerCase()), code);
  assert.equal(formatEnrollCode(parseEnrollCode(e.codeDr)), e.code);
  assert.equal(hex(await enrollToken(code)), e.token);
  const sign = h(V.identity.signPublic);
  const dh = h(V.identity.dhPublic);
  assert.equal(hex(await enrollProof(code, e.account, e.machine, sign, dh)), e.proof);
  assert.ok(await verifyEnrollProof(code, e.account, e.machine, sign, dh, h(e.proof)));
  assert.equal(await verifyEnrollProof(code, e.account, "m-2", sign, dh, h(e.proof)), false);
  for (const [plain, encoded] of [["", ""], ["f", "MY"], ["fo", "MZXQ"], ["foobar", "MZXW6YTBOI"]] as const) {
    assert.equal(base32(new TextEncoder().encode(plain)), encoded);
    assert.equal(new TextDecoder().decode(fromBase32(encoded.toLowerCase())!), plain);
  }
  assert.equal(fromBase32("MZ"), null);
  assert.throws(() => parseEnrollCode("RH2-AAAA-BBBB"));
  const body = e.code.slice(4);
  for (const other of ["DR2-", "DRP1-", "RHP1-", "DRR1-", "RHR1-", "D1-", "RH1DR1-", ""]) {
    assert.throws(() => parseEnrollCode(other + body), other);
  }
});

test("handshake replies, the freshness window and the hub's credit window match Rust", () => {
  for (const r of V.handshake.replies) {
    const body = decodeReplyBody(h(r.hex));
    assert.deepEqual(
      { ...body, chainHead: hex(body.chainHead), server: hex(body.server), entries: body.entries.map((e) => hex(encodeEntry(e))) },
      { status: r.status, chainSeq: r.chainSeq, chainHead: r.chainHead, needFrom: r.needFrom, server: r.server, entries: r.entries },
    );
    assert.equal(hex(encodeReplyBody(body)), r.hex);
  }
  assert.throws(() => decodeReplyBody(Uint8Array.from([3, ...new Uint8Array(8 + 32 + 8 + 2)])));
  assert.equal(FRESHNESS_MAX_AGE_MS, V.handshake.freshnessMaxAgeMs);
  assert.equal(INITIAL_CREDIT, V.flow.initialCredit);
});

test("the loopback bridge's heads and messages are Rust's, byte for byte", () => {
  const b = V.bridge;
  const req = { method: b.request.method, path: b.request.path, headers: b.request.headers };
  assert.equal(hex(encodeRequestHead(req)), b.request.hex);
  assert.deepEqual(decodeRequestHead(h(b.request.hex)), req);
  const res = { status: b.response.status, headers: b.response.headers };
  assert.equal(hex(encodeResponseHead(res)), b.response.hex);
  assert.deepEqual(decodeResponseHead(h(b.response.hex)), res);
  const wire = Uint8Array.from(b.messages.flatMap((m: Json) => [...h(m.hex)]));
  for (const m of b.messages) assert.equal(hex(bridgeMessage(m.kind, h(m.payload))), m.hex);
  // Reassembled whatever the chunking.
  for (const size of [1, 3, 7, wire.length]) {
    const reader = new MessageReader();
    const got: { kind: string; payload: string }[] = [];
    for (let i = 0; i < wire.length; i += size) {
      reader.push(wire.slice(i, i + size));
      for (let m = reader.next(); m; m = reader.next()) got.push({ kind: m.kind, payload: hex(m.payload) });
    }
    assert.deepEqual(got, b.messages.map((m: Json) => ({ kind: m.kind, payload: m.payload })));
  }
  const bad = new MessageReader();
  bad.push(Uint8Array.from([9, 0, 0, 0, 0]));
  assert.throws(() => bad.next());
});

test("applying an entry records when this verifier first saw it", async () => {
  const chain = entriesOf(V.chain.entries);
  const clock = ChainClock.live(5_000, 0);
  const state = await ChainState.verify(chain.slice(0, 2), undefined, clock);
  clock.nowMs = 9_000;
  await state.merge(chain, clock);
  assert.deepEqual([...clock.firstSeen.entries()].sort((a, b) => a[0] - b[0]).slice(0, 2), [
    [1, 5_000],
    [2, 9_000],
  ]);
  assert.ok(clock.isLive && !ChainClock.history().isLive);
});

