test("chain v2: removing a device that came back with the recovery words voids the account's words, as it always did", async () => {
  // Write gate: the v3 rule (only the words a device knows) left v2 alone, or old and new verifiers would split.
  const v = V.chainV3.v2RecoveryRemoval;
  const state = await ChainState.verify(entriesOf(v.entries), undefined, hist());
  assert.equal(state.isV3, false);
  assert.equal(hex(state.head), v.state.head);
  assert.equal(state.currentRecoveryKey, v.state.recoveryKey);
  assert.equal(state.currentRecoveryKey, null, "newer words set after it came back went too (v2)");
  assert.deepEqual(
    state.allDevices().map((d) => ({ id: d.info.id, status: d.status.type, viaRecovery: d.viaRecovery })),
    v.state.devices.map((d: Json) => ({ id: d.id, status: d.status, viaRecovery: d.viaRecovery })),
  );
});

test("the dialogs' voidsRecoveryWords says what the chain will rule, v3 and v2", async () => {
  const v = V.chainV3;
  const entries = entriesOf(v.entries);
  const at = async (label: string) => ChainState.verify(entries.slice(0, v.steps.find((s: Json) => s.label === label).seq + 1), undefined, hist());
  // d-w set the words: demoting it voids them.
  assert.equal((await at("setRecoveryW")).voidsRecoveryWords("d-w", "demotion"), true);
  // d-s came back with RSK4; RSK5 was set since: neither demoting nor removing it voids RSK5.
  const newer = await at("setRecovery5");
  assert.equal(newer.voidsRecoveryWords("d-s", "demotion"), false);
  assert.equal(newer.voidsRecoveryWords("d-s", "removal"), false);
  assert.equal(newer.voidsRecoveryWords("dev-0", "removal"), true, "it set RSK5");
  // d-t came back with the current RSK5: removing it voids them.
  assert.equal((await at("approveT")).voidsRecoveryWords("d-t", "removal"), true);
  // After the words went, nothing more to void.
  assert.equal((await at("removeT")).voidsRecoveryWords("dev-0", "removal"), false, "no words left to void");
  // v2: removing a device that came back with any words voids the account's, newer ones too.
  const v2 = await ChainState.verify(entriesOf(v.v2RecoveryRemoval.entries).slice(0, -1), undefined, hist());
  assert.equal(v2.voidsRecoveryWords("dev-r", "removal"), true);
});
